entries[314252] = { ["name"] = "Uraels Endgültigkeit", ["text"] = "Animabonus\nSofort\nNachdem Ihr einen Gegner mit 'Strahlender Funke' getroffen habt, wird der Schaden Eures vierten darauf folgenden direkten Schadenszaubers gegen dieses Ziel um zusätzlich 600% erhöht." }
entries[314253] = { ["name"] = "Gebet des Magiers", ["text"] = "Animabonus\nSofort\nDie Gruppe des Magiers erhält 800% des von 'Strahlender Funke' verursachten Schadens als Heilung zurück." }
entries[314254] = { ["name"] = "Atem der Zuflucht", ["text"] = "Animabonus\nSofort\nDie Phiole des Gleichmuts Eures Provosten schließt die Abklingzeit von 'Waffen der Ordnung' ab." }
