entries[314256] = { ["name"] = "Schlundverdunkelte Pantoffeln", ["text"] = "Animabonus\nSofort\nRollen, während 'Waffen der Ordnung' aktiv ist, verschießt einen Blitz aus Strahlenenergie auf einen Gegner in der Nähe und fügt ihm Arkanschaden zu." }
