entries[314264] = { ["name"] = "Mächtiger Klöppel", ["text"] = "Animabonus\nSofort\nEinsatz von 'Göttlicher Glockenschlag' betäubt alle Gegner innerhalb von 30 Metern für 3 Sek." }
entries[314266] = { ["name"] = "Glaubensstein", ["text"] = "Animabonus\nSofort\nDer Einsatz von 'Befreiung' schließt die Abklingzeit von 'Blinder Glaube' ab." }
