entries[314268] = { ["name"] = "Zweiter Chor", ["text"] = "Animabonus\nSofort\nDie Dauer des positiven Effekts von 'Blinder Glaube' ist um 50% erhöht." }
entries[314269] = { ["name"] = "Mal des blendenden Glaubens", ["text"] = "Animabonus\nSofort\nWenn einem Gegner Schaden zugefügt wird, bei dem die Effekte von 'Blinder Glaube' aktiv sind, besteht eine sehr hohe Chance, dass er geblendet und für 6 Sek. desorientiert wird." }
entries[314270] = { ["name"] = "Erhörtes Gebet", ["text"] = "Animabonus\nSofort\n'Blinder Glaube' hat keine negativen Effekte mehr beim Ablauf. Stattdessen explodiert arkane Energie aus Euch heraus, fügt Gegnern innerhalb von 12 Metern (480% der Zaubermacht) Schaden zu und heilt Verbündete in diesem Bereich um (480% der Zaubermacht) Gesundheit." }
entries[314271] = { ["name"] = "Geschwärzter Schleier", ["text"] = "Animabonus\nSofort\n'Blinder Glaube' löst bei Euch 'Wahre Blindheit' aus, erhöht Euren Schaden und Eure Heilung um 200% und verringert erlittenen Schaden um 40%.\n\nWährend 'Wahre Blindheit' aktiv ist, könnt Ihr Eure Umgebung nicht sehen." }
