entries[314295] = { ["name"] = "Speerspitzen der Ewigkeit", ["text"] = "Animabonus\nSofort\nJedes Mal, wenn Ihr den Speer der Bastion werft und mindestens einen Gegner trefft, wird der sofortige Schaden des Speers um 20% erhöht. Bis zu 15-mal stapelbar.\n(3s Abklingzeit)" }
entries[314296] = { ["name"] = "Leerenkugel", ["text"] = "Sofort\nSpielercharaktere unter der Wirkung von ' Leerengeweckt ' können die Kugel durch Berühren in Blickrichtung umlenken.\n\nWenn die Kugel einen Spielercharakter berührt, der nicht unter der Wirkung von ' Leerengeweckt ' steht, erleidet er ' Schmähen '. Wenn die Kugel Königin Azshara, einen Ritualobelisken oder den Rand der Kammer berührt, löst sie ' Dunkler Kollaps ' aus und wird von diesem Ort aus umgelenkt.\n\nWenn die Kugel ein offenes Portal berührt, wird sie von der Leere verschlungen und löst sich harmlos auf." }
entries[314297] = { ["name"] = "Ritualfeld", ["text"] = "500 Meter Reichweite\nSofort\nVerursacht 5 Schattenschaden und stößt Spielercharaktere zurück, die versuchen, eine Ritualfeld zu betreten." }
entries[314298] = { ["name"] = "Drohendes Unheil", ["text"] = "Sofort\nVon ' Leerengeweckt ' betroffene Spielercharaktere, die mit einer Leerenkugel in Berührung kommen, werden 12 Sek. lang mit ' Drohendes Unheil ' belegt.\n\nWenn ' Drohendes Unheil ' 3 Stapel erreicht, löst das Opfer ' Untergang ' aus." }
entries[314299] = { ["name"] = "Drohendes Unheil" }
