entries[314304] = { ["name"] = "Gesang der Kaiserin", ["text"] = "Wirken in 2.5 sek.\nShek'zara singt den ' Gesang der Kaiserin ' und strahlt in alle Richtungen Schallwellen ab.\n\nWenn der ' Gesang der Kaiserin ' einen Spielercharakter berührt, wird dieser zum Schweigen gebracht und erleidet 3 Sek. lang alle 0.5 Sek. 753 Naturschaden." }
entries[314305] = { ["name"] = "Gesang der Kaiserin", ["text"] = "Unbegrenzte Reichweite\nSofort\nShek'zara singt den ' Gesang der Kaiserin ' und strahlt in alle Richtungen Schallwellen ab.\n\nWenn der ' Gesang der Kaiserin ' einen Spielercharakter berührt, wird dieser zum Schweigen gebracht und erleidet 3 Sek. lang alle 0.5 Sek. 753 Naturschaden." }
